import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.ClgMjOt7.js";const u=JSON.parse('{"title":"アプリケーション仕様","description":"Palleria 5.9.0-beta.1 の実装に基づく機能・状態・連携の仕様。","frontmatter":{"title":"アプリケーション仕様","description":"Palleria 5.9.0-beta.1 の実装に基づく機能・状態・連携の仕様。"},"headers":[],"relativePath":"dev/application-specification.md","filePath":"dev/application-specification.md","lastUpdated":1789107345000}'),l={name:"dev/application-specification.md"};function d(c,a,n,r,s,p){return t(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="アプリケーション仕様" tabindex="-1">アプリケーション仕様 <a class="header-anchor" href="#アプリケーション仕様" aria-label="Permalink to &quot;アプリケーション仕様&quot;">​</a></h1><p>このページは <code>app</code>、<code>rust/pixiv-api</code>、<code>rust/pallasync-core</code> の現行ソースを基準にした実装仕様です。将来の構想ではなく、リポジトリに実装されている振る舞いを記録します。</p><h2 id="対象と動作環境" tabindex="-1">対象と動作環境 <a class="header-anchor" href="#対象と動作環境" aria-label="Permalink to &quot;対象と動作環境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>仕様</th></tr></thead><tbody><tr><td>アプリケーション ID</td><td><code>com.yunfie.illustia</code></td></tr><tr><td>現行バージョン</td><td><code>5.9.0-beta.1</code>（<code>versionCode</code> 89）</td></tr><tr><td>最低 / target SDK</td><td>API 24（Android 7.0） / API 36</td></tr><tr><td>UI</td><td>Kotlin、Jetpack Compose、Navigation 3、Miuix KMP</td></tr><tr><td>ネイティブ層</td><td>Rust 2024 edition、UniFFI/JNI 経由で利用</td></tr><tr><td>Rust ABI</td><td><code>arm64-v8a</code>、<code>armeabi-v7a</code>、<code>x86_64</code></td></tr></tbody></table><p>Palleria は Pixiv 非公式クライアントであり、認証と作品取得には Pixiv API を利用します。起動時にはクラッシュハンドラー、画像ローダー、設定ストアを初期化し、最初のフレーム表示後にアカウント整合、ウィジェットのプレビュー生成、PallaSync の復旧・開始を非同期で実行します。</p><h2 id="利用者向け機能" tabindex="-1">利用者向け機能 <a class="header-anchor" href="#利用者向け機能" aria-label="Permalink to &quot;利用者向け機能&quot;">​</a></h2><h3 id="認証とアカウント" tabindex="-1">認証とアカウント <a class="header-anchor" href="#認証とアカウント" aria-label="Permalink to &quot;認証とアカウント&quot;">​</a></h3><ul><li>リフレッシュトークンおよび認可コードによるログインをサポートする。</li><li>複数アカウントを設定に保持し、アクティブアカウントを切り替えられる。</li><li>Android の <code>AccountAuthenticator</code> と <code>SyncAdapter</code> を公開する。同期用コンテンツプロバイダーは外部公開しない。</li></ul><h3 id="閲覧・検索・コレクション" tabindex="-1">閲覧・検索・コレクション <a class="header-anchor" href="#閲覧・検索・コレクション" aria-label="Permalink to &quot;閲覧・検索・コレクション&quot;">​</a></h3><ul><li>ホーム、ランキング、ブックマーク、検索、その他を基本タブとして表示する。Shorts Feed 有効時は検索タブ位置を Shorts Feed に置き換える。</li><li>タブ順、非表示タブ、起動タブを設定できる。表示タブは常に最低 2 個確保する。</li><li>イラスト詳細、画像ビューア、マンガ、ノベル、ユーザープロフィール、コメント、作品シリーズ、関連作品を提供する。</li><li>検索は対象、並び順、作品種別、期間、ブックマーク数の条件を保持する。ユーザー検索、候補、検索履歴、お気に入りタグ、ウォッチリストシリーズを扱う。</li><li>ブックマーク、フォロー、ミュート（作品・ユーザー・タグ）、閲覧履歴を扱う。閲覧履歴と検索履歴は個別に保存を無効化できる。</li></ul><h3 id="保存・オフライン・表示" tabindex="-1">保存・オフライン・表示 <a class="header-anchor" href="#保存・オフライン・表示" aria-label="Permalink to &quot;保存・オフライン・表示&quot;">​</a></h3><ul><li>単一または複数ページの作品をギャラリーへ保存し、ダウンロードキューとオフラインライブラリで管理する。</li><li>自動ダウンロード、自動ブックマーク、作者別・作品別フォルダー、同時ダウンロード数を設定できる。</li><li>画像品質はフィード、イラスト詳細、マンガ詳細、全画面で個別に設定する。画像キャッシュ、Wi-Fi 限定スマートキャッシュ、低 RAM 端末向けのデコーダー抑制を備える。</li><li>ライブ壁紙、ランキングウィジェット、作品ウィジェットを提供する。壁紙はソース、更新契機・間隔、並び順、表示倍率、背景、クロスフェード、センシティブ作品の除外を設定できる。</li></ul><h3 id="外観・プライバシー・補助機能" tabindex="-1">外観・プライバシー・補助機能 <a class="header-anchor" href="#外観・プライバシー・補助機能" aria-label="Permalink to &quot;外観・プライバシー・補助機能&quot;">​</a></h3><ul><li>言語、フォント、テーマ、Dynamic Color、AMOLED、画面遷移、触覚フィードバック、グリッド列数、カード表示、詳細セクション順を設定できる。</li><li>PIN と生体認証によるアプリロック、失敗回数によるクールダウン、セキュアウィンドウ、履歴画面の秘匿、電卓アイコン／名称への偽装を提供する。</li><li>クリップボード検出、更新確認と APK ダウンロード、Discord RPC、任意のクラッシュテレメトリを提供する。テレメトリの既定値は無効で、同意後だけ SDK を有効化する。</li></ul><h2 id="画面・外部起動" tabindex="-1">画面・外部起動 <a class="header-anchor" href="#画面・外部起動" aria-label="Permalink to &quot;画面・外部起動&quot;">​</a></h2><p>画面識別子は <code>AppRoute</code> で型安全に表現する。値を伴う遷移は検索結果（検索語）、タグ検索（タグ）、作品詳細（作品 ID）、ユーザープロフィール（ユーザー ID）、端末別閲覧履歴（端末 ID・名称）である。設定配下には一般、画像、ブックマーク、アカウント、データ、ミュート、プライバシー、実験的機能、更新、Discord、PallaSync の各画面を置く。</p><p>外部からはテキスト・画像の共有、<code>PROCESS_TEXT</code>、Pixiv 関連 HTTP(S) URL、<code>pixiv://</code>・<code>palleria://</code> スキームを受け取る。ファイル共有には <code>FileProvider</code> を用い、外部にファイルパスを直接公開しない。</p><h2 id="データと状態の所有者" tabindex="-1">データと状態の所有者 <a class="header-anchor" href="#データと状態の所有者" aria-label="Permalink to &quot;データと状態の所有者&quot;">​</a></h2><table tabindex="0"><thead><tr><th>種類</th><th>保存先・責務</th></tr></thead><tbody><tr><td>UI 状態</td><td><code>IllustiaViewModel</code> と画面の Compose 状態。<code>StateFlow</code> とコルーチンで更新する。</td></tr><tr><td>アプリ設定</td><td><code>SettingsStore</code> が <code>AppSettings</code> を保存・公開する。一般設定は Preferences DataStore、秘密値は EncryptedSharedPreferences、コレクションの一部は Room を併用する。</td></tr><tr><td>Pixiv データ</td><td><code>IllustiaRepository</code> が認証、作品、検索、ブックマーク、フォロー等を API クライアントへ委譲する。</td></tr><tr><td>同期キュー</td><td><code>pallasync_database</code>（Room）。outbox、チェーン状態、端末、受信 inbox を保存する。</td></tr><tr><td>画像キャッシュ</td><td>Coil。<code>cacheDir/image_cache</code> に保存し、設定された MB 上限を適用する。</td></tr></tbody></table><p>秘密値（リフレッシュトークン、Discord トークン等）をログ、仕様例、テレメトリに出力してはならない。</p><h2 id="ネットワークとエラー分類" tabindex="-1">ネットワークとエラー分類 <a class="header-anchor" href="#ネットワークとエラー分類" aria-label="Permalink to &quot;ネットワークとエラー分類&quot;">​</a></h2><ul><li>共有 HTTP クライアントは全体 8、ホストあたり 4 の同時リクエスト上限、接続 12 秒、読書き 20 秒、呼び出し全体 30 秒のタイムアウトを持つ。</li><li>Pixiv API URL は HTTPS、<code>app-api.pixiv.net</code>、443 番ポート、埋込み認証情報なしに限定して検証する。</li><li>PallaSync URL は HTTP(S) のみ許可し、クエリ、フラグメント、埋込み認証情報を拒否する。</li><li>PallaSync は HTTP 410 をチェーン消失、429 と 5xx を再試行可能、その他の非 2xx をプロトコルエラーとして分類する。</li></ul><h2 id="pallasync-プロトコル" tabindex="-1">PallaSync プロトコル <a class="header-anchor" href="#pallasync-プロトコル" aria-label="Permalink to &quot;PallaSync プロトコル&quot;">​</a></h2><p>PallaSync はチェーン単位の暗号化イベント同期である。プロトコル版は <code>2.0</code>、標準の受信ページサイズは 200 件で、relay cursor と Lamport clock を永続化する。同期対象はお気に入りタグ、検索履歴、ミュート設定、閲覧履歴の各 v1/v2 スキーマで、イベント操作は <code>upsert</code> または <code>delete</code> である。</p><p>レコードは暗号化ペイロード、チェーン ID、端末 ID、作成時刻、署名を持つ。Rust コアは ChaCha20-Poly1305、Ed25519、X25519/HPKE、HKDF、PBKDF2、BIP39 を利用する。受信レコードは inbox に耐久保存してから適用し、復号・検証・スキーマ処理に失敗したものは隔離する。初回 pull 完了前のローカル変更は <code>pending_initial_merge</code> として待機し、マージ後に送信キューへ投入する。</p><h2 id="実装上の境界" tabindex="-1">実装上の境界 <a class="header-anchor" href="#実装上の境界" aria-label="Permalink to &quot;実装上の境界&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Compose 画面 / ViewModel</span></span>
<span class="line"><span>          ↓</span></span>
<span class="line"><span>IllustiaRepository / SettingsStore / PalleriaSyncCoordinator</span></span>
<span class="line"><span>          ↓                    ↓                 ↓</span></span>
<span class="line"><span>Pixiv API クライアント      AppSettings       Room outbox/inbox</span></span>
<span class="line"><span>          ↓                                      ↓</span></span>
<span class="line"><span> Rust pixiv-api (UniFFI)                 Rust pallasync-core (JNI)</span></span></code></pre></div><p><code>pixiv-api</code> は Pixiv 応答の転送・復号・モデル変換、<code>pallasync-core</code> は同期暗号プリミティブを担当する。Android 側は UI、永続化、Android 統合、HTTP 実行、同期ライフサイクルを担当する。</p><h2 id="変更時の確認事項" tabindex="-1">変更時の確認事項 <a class="header-anchor" href="#変更時の確認事項" aria-label="Permalink to &quot;変更時の確認事項&quot;">​</a></h2><ul><li>設定値を追加・変更する場合は、<code>AppSettings</code>、保存・復元処理、必要に応じて同期用投影とイベントスキーマを同時に更新する。</li><li>公開コンポーネントや URL 受信規則を変更する場合は、Manifest の <code>exported</code>、権限、受信データ検証を確認する。</li><li>PallaSync の wire 形式、暗号処理、スキーマ名を変更する場合は、既存端末との互換性、inbox 隔離、移行処理を確認する。</li><li>Rust API を変更する場合は UniFFI Kotlin バインディングと 3 ABI のネイティブライブラリを再生成する。</li></ul>`,30)])])}const P=e(l,[["render",d]]);export{u as __pageData,P as default};
